const cashOf = (terms: readonly Term[]) => terms.filter(term => term.kind === "cash" && term.giver === "proposer").reduce((sum, term) => sum + (term.amount ?? 0), 0);

/** NG-7: the terms with the counterpart's consent (a marriage offer always asks it). */
function withConsent(terms: readonly Term[]): readonly Term[] {
  return terms.some(term => term.kind === "consent") ? terms : [...terms, { kind: "consent", giver: "counterpart" }];
}

// --- NG-7 the offer and the counter -------------------------------------------------------------------------------------

/**
 * NG-7: the lord's marriage offer — weighed now and answered by the seed's draw: accepted (the contract is made),
 * countered (the counter waits a season for the lord), or refused. Refused offers (`marriageRefusal`) change nothing.
 */
export function proposeMarriage(state: GameState, offered: readonly Term[], groomId?: string): GameState {
  if (marriageRefusal(state, offered, groomId) !== null) return state;
  const { groom, bride } = marriageCandidates(state, groomId);
  const terms = withConsent(offered);
  const diplomacy = diplomacyOf(state);
  const ordinal = diplomacy.nextNegotiation;
  const acceptance = evaluateOffer(state, LORD, COUNTERPART, terms);
  const accepted = offerDraw(state, ordinal) < acceptance.permille;
  const counter = accepted ? null : counterOffer(state, LORD, COUNTERPART, terms, `negotiation-${ordinal}`);
  const negotiation: Negotiation = { id: `negotiation-${ordinal}`, proposer: LORD, counterpart: COUNTERPART, purpose: "marriage",
    groomId: groom!.id, brideId: bride!.id, terms, acceptance, status: accepted ? "accepted" : counter === null ? "rejected" : "countered",
    ...(counter === null ? {} : { counter }), tick: state.tick, deadline: state.tick + COUNTER_ANSWER_TICKS };
  const next = withDiplomacy(state, { ...diplomacy, negotiations: [...diplomacy.negotiations, negotiation], nextNegotiation: ordinal + 1 });
  return accepted ? contract(next, negotiation, terms) : next;

function contract(state: GameState, negotiation: Negotiation, terms: readonly Term[]): GameState {
  let next = state;
  const cash = cashOf(terms);
  if (cash > 0) {
    const posted = postLedgerEntries(next, [{ account: "cash", category: "marriage_portion", amount: -cash,
      sourceRefs: [{ type: "claim", id: negotiation.id, detail: "marriage" }, { type: "actor", id: negotiation.counterpart }] }]);
    next = { ...next, ledger: posted.ledger, treasuryCoin: posted.treasuryCoin };
  }
  const claimed = raiseClaim(next, { claimant: LORD, estateId: MARRIAGE_ESTATE_ID, basis: "marriage" });
  const claimId = estatesOf(claimed).claims.at(-1)!.id;
  let diplomacy = contractPromises(diplomacyOf(claimed), negotiation, terms, state.tick);
  diplomacy = { ...diplomacy, relations: { ...diplomacy.relations, [negotiation.counterpart]: (diplomacy.relations[negotiation.counterpart] ?? 0) + CONTRACT_RELATION_GAIN } };
  const groomed = groomToManor(claimed, negotiation.groomId);
  // FIX-13 (NG-5b): what is not cash waits — the jointure for the groom's death, the deferred debt for the inheritance.
  const jointure = terms.find(term => term.kind === "jointure" && term.giver === "proposer")?.pieceId;
  const deferred = terms.filter(term => term.kind === "debt_after_inheritance" && term.giver === "proposer").reduce((sum, term) => sum + (term.amount ?? 0), 0);
  const plan: MarriagePlan = { negotiationId: negotiation.id, groomId: groomed.groomId, brideId: negotiation.brideId, estateId: MARRIAGE_ESTATE_ID,
    contractedTick: state.tick, stage: "contracted", claimId, events: {}, ...(jointure === undefined ? {} : { jointurePieceId: jointure }),
    ...(deferred > 0 ? { deferredDebt: deferred } : {}) };
  return withDiplomacy(groomed.state, { ...diplomacy, marriage: plan });
}

export function counterOffer(state: GameState, proposer: string, counterpart: string, terms: readonly Term[], key: string):
  { readonly terms: readonly Term[]; readonly changes: readonly TermChange[]; readonly acceptance: Acceptance } | null {
  const greed = hashSeed(state.seed, "negotiation-greed", counterpart.length, key.length) % (GREED_MAX + 1);
  const target = ACCEPT_THETA + COUNTER_MARGIN + greed;
  let draft: Term[] = terms.filter(term => !redLine(state, term));
  let acceptance = evaluateOffer(state, proposer, counterpart, draft);
  for (const kind of COUNTER_DESIRES) {
    if (acceptance.score >= target) break;
    if (kind === "political_support") {
      if (draft.some(term => term.kind === kind)) continue;
      draft = [...draft, { kind, giver: "proposer", years: 2 }];
    } else if (kind === "jointure") {
      // FIX-13 (NG-5b): one jointure, on the first piece the lord holds that can carry it.
      const piece = jointurePiece(state);
      if (draft.some(term => term.kind === kind) || piece === null) continue;
      draft = [...draft, { kind, giver: "proposer", pieceId: piece }];
    } else {
      const per = (MATERIAL_PER_PENNY[kind] ?? 0) * (kind === "pension" ? 5 : 1);
      const material = acceptance.reasons.find(reason => reason.name === "material")?.value ?? 0;
      const room = Math.min(target - acceptance.score, MATERIAL_CAP - material);
      if (room <= 0 || per <= 0) continue;
      const have = amountOf(draft, kind);
      const more = Math.min(Math.ceil(room / per), desireRoom(state, counterpart, kind, draft) - have);
      if (more <= 0) continue;
      const years = kind === "pension" ? 5 : kind === "debt_assumption" ? debtInstalmentYears(state, have + more, debtInstalmentCap(state) - amountOf(draft, "pension")) : undefined;
      if (years === null) continue;
      draft = [...draft.filter(term => !(term.kind === kind && term.giver === "proposer")),
        { kind, giver: "proposer", amount: have + more, ...(years === undefined ? {} : { years }) }];
    }
    acceptance = evaluateOffer(state, proposer, counterpart, draft);
  }
  if (acceptance.score < target) return null;
  return { terms: draft, changes: termChanges(terms, draft), acceptance };
}

/** NG-2: the kinds of term. The lord's side gives the first five, the counterpart's the last five. */
export type TermKind =
  | "cash" | "pension" | "right_piece" | "political_support" | "debt_assumption"
  // FIX-13 (NG-5b): what is not cash — a jointure on one of the lord's pieces, the counterpart's debt repaid from the
  // estate once it is inherited.
  | "jointure" | "debt_after_inheritance"
  | "consent" | "inheritance_non_infringement" | "residence" | "land_use" | "wardship";

export interface Term {
  readonly kind: TermKind;
  /** Who gives it. */
  readonly giver: "proposer" | "counterpart";
  /** Pennies (cash, a year's pension, debt), years (pension, support, the debt's instalments — FIX-12), or nothing. */
  readonly amount?: number;
  readonly years?: number;
  /** A right piece's id (right_piece, land_use). */
  readonly pieceId?: string;
}

